cd /src/php-src && python3 - <<'PY'
import re, pathlib
path = pathlib.Path('ext/date/php_date.c')
s = path.read_text()
pattern = re.compile(r"static void update_errors_warnings\(timelib_error_container \*\*last_errors\) /\* \{\{\{ \*/
\{.*?
\} /\* \}\}\} \*/
", re.S)
new = """static void update_errors_warnings(timelib_error_container **last_errors) /* {{{ */
{
	if (DATEG(last_errors)) {
		timelib_error_container_dtor(DATEG(last_errors));
		DATEG(last_errors) = NULL;
	}

	if (last_errors == NULL || (*last_errors) == NULL) {
		return;
	}

	/*
	 * If there are warnings or errors, keep the container for
	 * DateTime::getLastErrors() and free it during request/module shutdown
	 * (where DATEG(last_errors) is destroyed).
	 *
	 * Otherwise, destroy it here.
	 */
	if ((*last_errors)->warning_count || (*last_errors)->error_count) {
		DATEG(last_errors) = *last_errors;
		return;
	}

	timelib_error_container_dtor(*last_errors);
	*last_errors = NULL;
} /* }}} */
"""
ns, n = pattern.subn(new, s)
if n != 1:
    raise SystemExit(f"Expected to replace 1 occurrence, replaced {n}")
path.write_text(ns)
print('patched', path)
PY

